def resample(path,step=.45):
 lens=np.r_[0,np.cumsum(np.linalg.norm(np.diff(path,axis=0),axis=1))]
 # preserve all knots so corners and end of retraced stems do not get cut off
 pts=[path[0]]
 for a,b in zip(path[:-1],path[1:]):
  n=max(1,int(np.ceil(np.linalg.norm(b-a)/step)))
  pts.extend(a+(b-a)*np.linspace(0,1,n+1)[1:,None])
 return np.array(pts)

def write_letter(name,practice=False,center=(-.12,-.1856),speed=.002):
 path=np.load(OUT/(name+'_path.npy'))
 p=resample(path,step=speed*.05/.00022186)
 if practice:
  x=center[0]-(p[:,1]-510)*.00022186
  y=center[1]-(p[:,0]-375)*.00022186
 else:
  x=-.1-(p[:,1]+.5-512)*.00022186
  y=-(p[:,0]+.5-512)*.00022186
 pts=np.stack([x,y,np.full(len(x),.0192)],axis=1)
 hover(x[0],y[0],.06)
 precise(lineposes([[x[0],y[0],.06],pts[0]],speed=.012)+[[*pts[0],*Q]]*10,note=name+' approach')
 precise([list(pt)+Q for pt in pts]+[[*pts[-1],*Q]]*10,note=name+' continuous letter')
 precise(lineposes([pts[-1],[x[-1],y[-1],.055]],speed=.012),note=name+' lift')
 hover(-.3,0,.15)
 obs=r.get_obs(cameras=['practice_cam','canvas_cam']);obs.save(str(OUT/('after_'+name+('_practice' if practice else ''))))
 for cam,im in obs.last.items(): Image.fromarray(im).save(OUT/(f'after_{name}_'+('practice_' if practice else '')+cam+'.png'))
 print('completed',name,'practice',practice,flush=True)
